constexpr int factorial(int n) {
  if (n == 0) return 1;
  return n * factorial(n - 1); 
}

int main() {
  constexpr int result = factorial(5); // Compile-time evaluation
  int runtimeResult = factorial(6);  // Runtime evaluation if 6 cannot be evaluated constexpr
  static_assert(result == 120, "Factorial calculation failed");
  return 0;
}
